-- =============================================================================
-- Shared migration 023 — dispatch_mechanism.
--
-- GENERATED by scripts/gen_registry_seed.py from registry/document_types.csv.
--
-- Which of the four Bronze->Silver write paths a doc_type_code routes
-- through: PDF_EXTRACTION (src/extraction/registry.py's extractor
-- registry), SALES_REGISTER (src/silver/sales_register.py, the one
-- hand-written loader), REGISTER_LOADER (src/silver/registers/catalog.py's
-- spec_for), or ARCHETYPE1_PROMOTE (src/silver/promote.py). Empty for a
-- document type with no upload-triggered write path yet (Stream A polled
-- types, or an in-scope type sampled but not yet built an extractor for).
-- NOT null: see field_contract's identical reasoning (migration 009).
-- =============================================================================

ALTER TABLE platform_ref.document_type
    ADD COLUMN IF NOT EXISTS dispatch_mechanism text NOT NULL DEFAULT '';

UPDATE platform_ref.document_type d
   SET dispatch_mechanism = v.mechanism
  FROM (VALUES
