ALTER TABLE platform_ref.document_type
    ADD CONSTRAINT document_type_dispatch_mechanism_values_ck
    CHECK (dispatch_mechanism IN ('ARCHETYPE1_PROMOTE', 'PDF_EXTRACTION', 'REGISTER_LOADER', 'SALES_REGISTER', ''));

-- Same scope guard field_contract/extraction_spec carry: a mechanism on an
-- out-of-scope row is unreachable code in table form.
ALTER TABLE platform_ref.document_type
    ADD CONSTRAINT document_type_dispatch_mechanism_scope_ck
    CHECK (dispatch_mechanism = '' OR in_scope);
